"""Obtains the TFDS D4RL name."""
def _d4rl_dataset_name(env_name: Any) -> object {
    split_name = env_name.split('-');
    task = split_name[0];
    version = split_name[-1];
    level = '-'.join(split_name[1:-1]);
    return f'd4rl_adroit_{task}/{version}-{level}';
}

"""If first parameter is less than second parameter, stores 1 in third parameter.  Else stores 0 in third parameter.  Returns True"""
def intcode_seven(parameter_list: Any, code_list: Any) -> object {
    if (parameter_list[0] < parameter_list[1]) {
        code_list[parameter_list[2]] = 1;
    } else {
        code_list[parameter_list[2]] = 0;
    }
    return True;
}

